using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Web.Script.Serialization;
sealed class StoryRule {public string ID,Title,Body,Cleanup;public bool Annual=true,Once;}
sealed class StorySave {public string Token;public List<StoryRule> Rules=new List<StoryRule>();}
sealed class CampaignStories {
 readonly TrainerSession session;readonly CampaignEngine engine;readonly string file;StorySave state=new StorySave();int lastYear=Int32.MinValue;public bool HasStories {get{return state.Rules.Count>0;}}public string Summary {get{return String.Join(" · ",state.Rules.Select(r=>r.Title));}}
 public CampaignStories(TrainerSession s,CampaignEngine e){session=s;engine=e;file=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CK3PersonalTrainer","stories.json");}
 string Gate {get{return "global_var:ck3t_v3_story_token = flag:"+state.Token;}}
 public async Task Restore(){if(!File.Exists(file))return;var saved=new JavaScriptSerializer().Deserialize<StorySave>(File.ReadAllText(file));if(saved==null || String.IsNullOrEmpty(saved.Token) || saved.Rules.Count==0)return;CampaignEngine.Key(saved.Token);var r=await session.Send("if = { limit = { has_global_variable = ck3t_v3_story_token global_var:ck3t_v3_story_token = flag:"+saved.Token+" } debug_log = \"CK3T_STORIES_RESTORE\" }",session.State.Player);if(r.Rows("CK3T_STORIES_RESTORE").Any())state=saved;}
 public async Task Revalidate(){lastYear=Int32.MinValue;state=new StorySave();session.SetStoryProtection("council",new uint[0]);await Restore();}
 void Save(){Directory.CreateDirectory(Path.GetDirectoryName(file));AtomicStorage.Write(file,new JavaScriptSerializer().Serialize(state));}
 public StoryRule Define(CampaignAction a,CampaignParameters p){string id=String.IsNullOrEmpty(a.story)?a.id.Replace("scenario_",""):a.story;if(id=="succession" || id=="inheritance")id+="_"+p.Character;if(id=="relic")id+="_"+(p.Object==null?"probe":p.Object.Identity);string owner="global_var:ck3t_story_owner_"+id,other="global_var:ck3t_story_other_"+id;string body="",cleanup="";bool annual=true,once=false;
  if(id.StartsWith("succession_")){annual=false;body=owner+" = { if = { limit = { is_alive = yes can_designate_heir_trigger = yes } ordered_in_global_list = { variable = ck3t_story_heirs_"+id+" limit = { is_alive = yes is_child_of = "+owner+" } position = 0 check_range_bounds = no save_scope_as = ck3t_preferred_heir "+owner+" = { if = { limit = { NOT = { designated_heir = scope:ck3t_preferred_heir } } set_designated_heir = scope:ck3t_preferred_heir scriptedtests_recalculate_succession = yes } } } } }";cleanup="clear_global_variable_list = ck3t_story_heirs_"+id;}
  else if(id.StartsWith("inheritance_")){annual=false;once=true;string transfer="create_title_and_vassal_change = { type = granted save_scope_as = ck3t_testament_change } $DISTRIBUTE{ if = { limit = { exists = holder previous_holder = "+owner+" $RECIPIENT = { is_alive = yes } } change_title_holder = { holder = $RECIPIENT government_base = holder change = scope:ck3t_testament_change } } } resolve_title_and_vassal_change = scope:ck3t_testament_change";body=engine.Expand(new CampaignAction{body=transfer},p);for(int i=p.Recipients.Count-1;i>=0;i--){body=body.Replace("global_var:ck3t_v3_recipient_"+i,"global_var:ck3t_story_recipient_"+id+"_"+i);cleanup+=" remove_global_variable = ck3t_story_recipient_"+id+"_"+i;}body="if = { limit = { has_global_variable = ck3t_story_done_"+id+" } debug_log = \"CK3T_STORY_ONCE_DONE\" } else_if = { limit = { "+owner+" = { is_alive = no } } "+body+" set_global_variable = { name = ck3t_story_done_"+id+" value = yes } debug_log = \"CK3T_STORY_ONCE_DONE\" }";}
  else if(id.StartsWith("relic_")){annual=false;once=true;string artifact="global_var:ck3t_story_artifact_"+id;body="if = { limit = { NOT = { exists = "+artifact+" } } debug_log = \"CK3T_STORY_ONCE_DONE\" } else_if = { limit = { "+owner+" = { is_alive = no } "+other+" = { is_alive = yes } } if = { limit = { "+other+" = { is_alive = yes } } "+artifact+" = { set_owner = { target = "+other+" generate_history = yes } } } debug_log = \"CK3T_STORY_ONCE_DONE\" } else_if = { limit = { "+owner+" = { is_alive = yes } "+artifact+" = { NOT = { artifact_owner = "+owner+" } } } debug_log = \"CK3T_STORY_ONCE_DONE\" }";body="if = { limit = { has_global_variable = ck3t_story_done_"+id+" } debug_log = \"CK3T_STORY_ONCE_DONE\" } else = { "+body.Replace("debug_log = \"CK3T_STORY_ONCE_DONE\"","set_global_variable = { name = ck3t_story_done_"+id+" value = yes } debug_log = \"CK3T_STORY_ONCE_DONE\"")+" }";body=body.Replace(owner+" = { is_alive = no } "+other+" = { is_alive = yes }",owner+" = { is_alive = no }");cleanup="remove_global_variable = ck3t_story_artifact_"+id;}
  else if(id=="crown")body="every_in_global_list = { variable = ck3t_v3_crowns limit = { exists = this } if = { limit = { exists = artifact_owner } artifact_owner = { add_stress = 20 add_tyranny = 5 add_gold = 1000 } } }";
  else if(id=="sword")body="every_in_global_list = { variable = ck3t_v3_swords limit = { exists = this } save_scope_as = ck3t_runtime_sword if = { limit = { exists = artifact_owner } artifact_owner = { if = { limit = { prowess >= 20 } add_prestige = 500 if = { limit = { prowess < 100 } add_prowess_skill = 2 "+Templates.Dirty+" } } else = { add_stress = 20 ordered_courtier = { limit = { is_alive = yes age >= 18 prowess >= 20 } order_by = prowess max = 1 check_range_bounds = no scope:ck3t_runtime_sword = { set_owner = { target = prev generate_history = yes } } } } ordered_courtier = { limit = { is_alive = yes age >= 18 } order_by = prowess max = 1 check_range_bounds = no add_personal_artifact_claim = scope:ck3t_runtime_sword } } } }";
  else if(id=="academy"){string skill=p.Arg.Replace("education_","").Replace("_focus","");if(!new[]{"diplomacy","martial","stewardship","intrigue","learning"}.Contains(skill))skill="learning";string trait="education_"+skill+"_4";body=owner+" = { house = { house_head = { every_child = { limit = { is_alive = yes age >= 6 age < 18 } if = { limit = { age < 16 } add_"+skill+"_skill = 3 add_learning_skill = 1 set_focus = "+CampaignEngine.Key(p.Arg)+" "+Templates.Dirty+" } else_if = { limit = { NOT = { has_variable = ck3t_academy_graduated } } "+String.Join(" ",engine.Catalogs["trait"].Where(x=>x.id.StartsWith("education_")).Select(x=>"remove_trait = "+x.id))+" add_trait = "+trait+" set_variable = ck3t_academy_graduated "+Templates.Dirty+" } } } } }";}
  else if(id=="rival")body="global_var:ck3t_rival_created = { house = { house_head = { if = { limit = { is_alive = yes } add_gold = 500 add_martial_skill = 1 add_intrigue_skill = 1 "+Templates.Dirty+" } } } }";
  else if(id=="council"){annual=false;string assign="";foreach(var pair in new[]{new[]{"chancellor","councillor_chancellor"},new[]{"marshal","councillor_marshal"},new[]{"steward","councillor_steward"},new[]{"spymaster","councillor_spymaster"},new[]{"chaplain","councillor_court_chaplain"}})assign+=" if = { limit = { var:ck3t_council_role = flag:"+pair[0]+" } global_var:ck3t_council_anchor.holder = { assign_councillor_type = { type = "+pair[1]+" target = scope:ck3t_council_person remove_existing_councillor = yes } } } ";body="every_in_global_list = { variable = ck3t_v3_immortal_council limit = { is_alive = yes } debug_log = \"CK3T_V3_OBJECT\" debug_log_scopes = no if = { limit = { exists = global_var:ck3t_council_anchor.holder NOT = { has_variable = ck3t_council_last_ruler var:ck3t_council_last_ruler = global_var:ck3t_council_anchor.holder } } save_scope_as = ck3t_council_person global_var:ck3t_council_anchor.holder = { add_courtier = scope:ck3t_council_person } "+assign+" set_variable = { name = ck3t_council_last_ruler value = global_var:ck3t_council_anchor.holder } } }";cleanup="remove_global_variable = ck3t_council_anchor";}

  else if(id=="secret")body=owner+" = { every_child = { limit = { is_alive = yes age >= 18 has_variable = ck3t_secret_years NOT = { has_variable = ck3t_secret_coup_done } } if = { limit = { exists = employer NOT = { employer = "+owner+" } } add_intrigue_skill = 1 add_gold = 200 change_variable = { name = ck3t_secret_years add = 1 } if = { limit = { var:ck3t_secret_years >= 3 employer = { is_landed = yes } } add_pressed_claim = employer.primary_title } if = { limit = { var:ck3t_secret_years >= 5 employer = { is_landed = yes } } save_scope_as = ck3t_agent_coup employer.primary_title = { save_scope_as = ck3t_coup_title } create_title_and_vassal_change = { type = granted save_scope_as = ck3t_secret_change } scope:ck3t_coup_title = { change_title_holder = { holder = scope:ck3t_agent_coup government_base = holder change = scope:ck3t_secret_change } } resolve_title_and_vassal_change = scope:ck3t_secret_change set_variable = ck3t_secret_coup_done } "+Templates.Dirty+" } } }";
  else if(id=="tournament")body=owner+" = { house = { house_head = { save_scope_as = ck3t_tournament_parent ordered_child = { limit = { is_alive = yes age >= 18 } order_by = { value = prowess multiply = 2 add = martial add = diplomacy add = stewardship } max = 1 check_range_bounds = no add_prestige = 500 add_gold = 200 scope:ck3t_tournament_parent = { if = { limit = { can_designate_heir_trigger = yes } set_designated_heir = prev } } } } } }";
  else if(id=="old_faith")body=owner+" = { if = { limit = { is_alive = yes } every_vassal_or_below = { set_character_faith = faith:"+CampaignEngine.Key(p.Arg)+" } add_piety = 100 } }";
  else if(id=="exile")body=other+" = { if = { limit = { is_alive = yes } add_gold = 500 add_prestige = 250 if = { limit = { is_at_war = no exists = global_var:ck3t_exile_goal.holder NOT = { global_var:ck3t_exile_goal.holder = this } } start_war = { casus_belli = claim target = global_var:ck3t_exile_goal.holder target_title = global_var:ck3t_exile_goal } } } }";
  else if(id=="founder")body="global_var:ck3t_story_founder = { house = { house_head = { add_prestige = 250 add_gold = 100 } } }";
  else if(id=="split")body=owner+" = { every_child = { limit = { is_alive = yes is_landed = yes } add_gold = 250 add_prestige = 100 } }";
  else if(id=="last_king")body=owner+" = { if = { limit = { is_alive = yes } add_gold = 250 add_prestige = 100 } }";
  return new StoryRule{ID=id,Title=a.title,Body=body,Annual=annual,Once=once,Cleanup=cleanup};
 }
 public void Preflight(CampaignAction a,CampaignParameters p){Define(a,p);Save();}
 public async Task Start(CampaignAction a,CampaignParameters p){var rule=Define(a,p);if(String.IsNullOrEmpty(rule.Body))return;if(String.IsNullOrEmpty(state.Token)){state.Token="s"+Guid.NewGuid().ToString("N");await session.Send("set_global_variable = { name = ck3t_v3_story_token value = flag:"+state.Token+" }",session.State.Player);}await session.Send("set_global_variable = { name = ck3t_story_owner_"+rule.ID+" value = this }",p.Character);if(a.other)await session.Send("set_global_variable = { name = ck3t_story_other_"+rule.ID+" value = this }",p.Other);if(rule.ID.StartsWith("relic_"))await session.Send("set_global_variable = { name = ck3t_story_artifact_"+rule.ID+" value = global_var:ck3t_v3_selected }",session.State.Player);if(rule.ID.StartsWith("succession_")){string list="ck3t_story_heirs_"+rule.ID;await session.Send("clear_global_variable_list = "+list,session.State.Player);foreach(uint id in p.Recipients)await session.Send("add_to_global_variable_list = { name = "+list+" target = this }",id);}if(rule.ID.StartsWith("inheritance_"))for(int i=0;i<p.Recipients.Count;i++)await session.Send("set_global_variable = { name = ck3t_story_recipient_"+rule.ID+"_"+i+" value = this }",p.Recipients[i]);if(rule.Once)await session.Send("remove_global_variable = ck3t_story_done_"+rule.ID,session.State.Player);int year=await Year();await session.Send("set_global_variable = { name = ck3t_story_year_"+rule.ID+" value = "+year+" }",session.State.Player);state.Rules.RemoveAll(r=>r.ID==rule.ID);state.Rules.Add(rule);lastYear=Int32.MinValue;Save();await Tick();}
 public Task<int> ReadYear(){return Year();}
 async Task<int> Year(){var r=await session.Send("debug_log = \"CK3T_YEAR|[GetCurrentDate.GetYear]\"",session.State.Player);int year;if(!Int32.TryParse(r.Rows("CK3T_YEAR|").LastOrDefault(),out year))throw new InvalidOperationException(Lang.T("Не удалось прочитать игровой год для сценариев."));return year;}
 public async Task Syntax(CampaignAction a,CampaignParameters p){var rule=Define(a,p);if(String.IsNullOrEmpty(rule.Body))return;rule.Body=rule.Body.Replace("every_in_global_list = { variable = ck3t_v3_crowns","every_character_artifact = {").Replace("every_in_global_list = { variable = ck3t_v3_swords","every_character_artifact = {");await session.Send("set_global_variable = { name = ck3t_story_owner_"+rule.ID+" value = this } set_global_variable = { name = ck3t_story_other_"+rule.ID+" value = this } if = { limit = { always = no } "+rule.Body+" } remove_global_variable = ck3t_story_owner_"+rule.ID+" remove_global_variable = ck3t_story_other_"+rule.ID,session.State.Player);}
 public async Task Tick(){if(!HasStories)return;int year=await Year();var completed=new List<StoryRule>();foreach(var r in state.Rules){if(r.Annual && year==lastYear)continue;string condition=Gate+(r.Annual?" global_var:ck3t_story_year_"+r.ID+" < "+year:"");string body="if = { limit = { "+condition+" } "+r.Body+(r.Annual?" set_global_variable = { name = ck3t_story_year_"+r.ID+" value = "+year+" }":"")+" "+Templates.Flush+" debug_log = \"CK3T_STORY_TICK:"+r.ID+"\" }";var reply=await session.Send(body,session.State.Player);if(r.Once && reply.Rows("CK3T_STORY_ONCE_DONE").Any())completed.Add(r);if(r.ID=="council"){var people=CampaignEngine.ParseObjects(reply.Text,"person","");session.SetStoryProtection("council",people.Select(o=>UInt32.Parse(o.Identity)));}if(r.Annual && reply.Rows("CK3T_STORY_TICK:"+r.ID).Any() && session.Progress!=null)session.Progress(r.Title+Lang.T(" · обработан игровой год ")+year);}foreach(var r in completed){state.Rules.Remove(r);await session.Send((r.Cleanup??"")+" remove_global_variable = ck3t_story_owner_"+r.ID+" remove_global_variable = ck3t_story_year_"+r.ID,session.State.Player);}if(completed.Count>0)Save();lastYear=year;}
 public async Task StopAll(){if(!HasStories)return;await session.Send("if = { limit = { "+Gate+" } "+String.Join(" ",state.Rules.Select(r=>(r.Cleanup??"")+" remove_global_variable = ck3t_story_owner_"+r.ID+" remove_global_variable = ck3t_story_other_"+r.ID+" remove_global_variable = ck3t_story_year_"+r.ID))+" remove_global_variable = ck3t_v3_story_token }",session.State.Player);session.SetStoryProtection("council",new uint[0]);state=new StorySave();Save();}
}
